import re
from datetime import datetime
from dateutil import parser as date_parser


def extract(text: str) -> dict:
    person_match = re.search(r'Appointment\s+confirmed\s+for\s+(.+?)\s+with\s+Dr\.', text, re.IGNORECASE | re.DOTALL)
    if not person_match:
        raise ValueError('Missing appointment person label')
    person = re.sub(r'\s+', ' ', person_match.group(1)).strip()

    date_match = re.search(r'\bDate:\s*([^\n\r]+)', text, re.IGNORECASE)
    if not date_match:
        raise ValueError('Missing Date label')
    date_str = date_match.group(1).strip()
    try:
        due_date = date_parser.parse(date_str, dayfirst=True).date().isoformat()
    except Exception as e:
        raise ValueError('Invalid appointment date') from e

    time_match = re.search(r'\bTime:\s*([^\n\r]+)', text, re.IGNORECASE)
    if not time_match:
        raise ValueError('Missing Time label')
    time_str = time_match.group(1).strip()
    try:
        event_time = date_parser.parse(time_str).strftime('%H:%M')
    except Exception as e:
        raise ValueError('Invalid appointment time') from e

    return {
        'type': 'meeting',
        'provider': 'Apollo Clinic',
        'currency': 'INR',
        'due_date': due_date,
        'event_time': event_time,
        'person': person,
    }
